import { tidyGloss } from '../core/gloss';
import { transliterate } from '../core/translit';
import type { Entry } from '../core/types';
import raw from './vocab-data.json';

/**
 * The starter deck, generated by tools/deck/build-vocab.mjs from Wikidata lexemes
 * (CC0). The Malayalam and its English meaning come from that dataset, not from a
 * model, so these are `dataset` entries. They are dictionary forms with no
 * formal/spoken label, hence the `neutral` register. The romanization is computed
 * by the rule-based transliterator, never typed by hand.
 */
interface RawWord {
  id: string; // Wikidata lexeme id, e.g. "L480"
  ml: string;
  en: string;
  topic: string;
  audio: string; // path under assets/audio; the clip file exists only once it has been downloaded (see AUDIO)
  commonsFile: string;
  speaker: string | null;
}

const TITLES: Record<string, string> = {
  greetings: 'Greetings',
  pronouns: 'Pronouns and question words',
  family: 'Family and people',
  numbers: 'Numbers',
  food: 'Food and drink',
  body: 'The body',
  home: 'Home',
  places: 'Places and travel',
  time: 'Time and days',
  colours: 'Colours',
  nature: 'Nature and animals',
  verbs: 'Common verbs',
  adjectives: 'Describing things',
  film_music: 'Film and music',
  daily_life: 'Daily life',
  directions: 'Directions',
};

const titleOf = (id: string): string =>
  TITLES[id] ?? id.replace(/_/g, ' ').replace(/^./, (c) => c.toUpperCase());

export const VOCAB: Entry[] = (raw as RawWord[]).map((w) => ({
  id: `word:${w.id}`,
  kind: 'word',
  register: 'neutral',
  ml: w.ml,
  roman: transliterate(w.ml),
  en: tidyGloss(w.en),
  provenance: 'dataset',
  tags: [w.topic],
  audio: w.audio,
  source: `Wikidata lexeme ${w.id} (CC0); audio ${w.commonsFile} via Wikimedia Commons`,
}));

export const VOCAB_BY_ID: Map<string, Entry> = new Map(VOCAB.map((e) => [e.id, e]));

export interface Topic {
  id: string;
  title: string;
  entryIds: string[];
}

/** Topics in the order they first appear in the deck. */
export const TOPICS: Topic[] = (() => {
  const byId = new Map<string, Topic>();
  for (const e of VOCAB) {
    const id = e.tags[0];
    if (!byId.has(id)) byId.set(id, { id, title: titleOf(id), entryIds: [] });
    byId.get(id)!.entryIds.push(e.id);
  }
  return [...byId.values()];
})();
